
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS member_sessions(token_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS member_profiles(member_id TEXT PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE,nickname TEXT NOT NULL,gender TEXT NOT NULL CHECK(gender IN ('男','女')),age INTEGER NOT NULL CHECK(age BETWEEN 18 AND 99),city TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
